<?php
declare(strict_types=1);
function sc_mail_ready(array $c): bool { if(empty($c['mail_enabled']))return false;if(empty($c['resend_api_key'])||empty($c['mail_from'])||empty($c['mail_to'])||!is_array($c['mail_to']))sc_fail(503,'E-posta gönderim ayarları eksik.');foreach($c['mail_to'] as $email)if(!filter_var($email,FILTER_VALIDATE_EMAIL))sc_fail(503,'E-posta alıcısı geçersiz.');if(!function_exists('curl_init'))sc_fail(503,'E-posta için PHP cURL eklentisi gerekli.');return true; }
function sc_send_mail(array $c,array $a,array $business,string $jobId): void { $b=sc_find_barber($business,$a['barberId']);$text=implode("\n",[$business['name'],'Yeni randevu kaydedildi.','Müşteri: '.$a['name'],'Telefon: '.$a['phone'],'Çalışan: '.($b['name']??'Çalışan'),'Tarih: '.$a['date'],'Saat: '.$a['time'].' (Türkiye saati)','Hizmetler: '.implode(' + ',array_column($a['services'],'name')),'Tutar: '.$a['total'].' TL'.($a['priceFrom']?' ve üzeri':''),'Randevu kodu: '.$a['code']]);$ch=curl_init('https://api.resend.com/emails');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$c['resend_api_key'],'Idempotency-Key: booking-'.$jobId],CURLOPT_POSTFIELDS=>json_encode(['from'=>$c['mail_from'],'to'=>$c['mail_to'],'subject'=>$business['name'].' · Yeni randevu · '.$a['code'],'text'=>$text],JSON_THROW_ON_ERROR)]);curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$err=curl_errno($ch);curl_close($ch);if($err||$status<200||$status>=300)throw new RuntimeException('Gönderim hizmeti isteği tamamlanamadı.'); }
function sc_drain_mail(PDO $db,array $c): void { if(!sc_mail_ready($c))return;$jobs=sc_query($db,"SELECT * FROM sc_email_outbox WHERE status='pending' AND next_attempt<=? ORDER BY created_at LIMIT 10",[sc_ms()])->fetchAll();foreach($jobs as $job){$row=sc_query($db,'SELECT * FROM sc_appointments WHERE id=?',[$job['booking_id']])->fetch();if(!$row||$row['status']==='cancelled'){sc_query($db,"UPDATE sc_email_outbox SET status='skipped' WHERE id=?",[$job['id']]);continue;}try{sc_send_mail($c,sc_booking($row),sc_business($db),$job['id']);sc_query($db,"UPDATE sc_email_outbox SET status='sent',attempts=attempts+1,last_error=NULL WHERE id=?",[$job['id']]);}catch(Throwable){$n=(int)$job['attempts']+1;sc_query($db,'UPDATE sc_email_outbox SET status=?,attempts=?,next_attempt=?,last_error=? WHERE id=?',[$n>=5?'failed':'pending',$n,sc_ms()+min(60,2**$n)*60000,'Gönderim hizmetine ulaşılamadı.',$job['id']]);}} }
